afterEach(async () => {
    for (const collection of ['audioTracks', 'albums', 'artists', 'organizations', 'imageAssets']) assert.equal(await getDb()!.collection(collection).countDocuments({}), 0, `${collection} must stay unchanged`);
});
after(async () => {
    await new Promise<void>(resolve => server?.close(() => resolve())); await harness?.stop();
    if (previousReady === undefined) delete process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY; else process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = previousReady;
    guard.restore(); assert.deepEqual(guard.attempts, []);
});

test('Video authentication, current-role and cookie-viewer guards precede malformed body parsing', async () => {
    assert.equal((await request(root, 'POST', '{broken', '')).status, 401);
    assert.equal((await request(root, 'POST', '{broken', userToken)).status, 403);
    const cookie = { Cookie: `session_token=${token}` };
    assert.equal((await request(root, 'GET', undefined, '', cookie)).status, 409);
    assert.equal((await request(root, 'GET', undefined, '', { ...cookie, 'X-Finitude-Account-Viewer': otherAdmin.toHexString() })).status, 409);
    assert.equal((await request(root, 'POST', '{broken', '', { ...cookie, Origin: base, 'X-Finitude-Account-Viewer': ordinary.toHexString() })).status, 409);
    const response = await request(root, 'GET', undefined, '', { ...cookie, 'X-Finitude-Account-Viewer': actor.toHexString() });
    assert.equal(response.status, 200); assert.equal(response.headers.get('X-Finitude-Account-Viewer'), actor.toHexString());
    await getDb()!.collection('users').updateOne({ _id: actor }, { $set: { role: 'user' } });
    assert.equal((await request(root, 'POST', '{broken')).status, 403);
    assert.equal((await request('/adjacent', 'GET', undefined, '')).status, 200);
    assert.equal(puts, 0); assert.equal(await getDb()!.collection('adminVideoProjects').countDocuments({}), 0);
});

test('cookie Video mutations reject cross-origin requests before parsing or private storage work', async () => {
    const headers = { Cookie: `session_token=${token}`, 'X-Finitude-Account-Viewer': actor.toHexString() };
    assert.equal((await request(root, 'POST', '{broken', '', { ...headers, Origin: 'https://invalid.example.test', 'Sec-Fetch-Site': 'cross-site' })).status, 403);
    assert.equal((await request(root, 'POST', '{broken', '', { ...headers, Origin: base, 'Sec-Fetch-Site': 'same-origin' })).status, 400);
    const value = { operationId: randomUUID(), filename: 'Lorem.MOV', byteLength: 3 };
    const accepted = await request(root, 'POST', value, '', { ...headers, Origin: base, 'Sec-Fetch-Site': 'same-origin' });
    assert.equal(accepted.status, 201); assertPrivateDto(await accepted.json()); assert.equal(puts, 0);
});

test('Video creation is owner-scoped, idempotent and strict about filenames, lengths and server-owned fields', async () => {
    const { body, result } = await create();
    assertPrivateDto(result); assert.equal(result.item.draft.attribution, 'self'); assert.equal(result.item.draft.publicName, '');
    const replay = await request(root, 'POST', body); assert.equal(replay.status, 201); assert.equal((await replay.json() as any).item.id, result.item.id);
    assert.equal((await request(root, 'POST', { ...body, filename: 'Different.MOV' })).status, 409);
    for (const patch of [{ ownerId: otherAdmin.toHexString() }, { actorId: otherAdmin.toHexString() }, { filename: '../Lorem.MOV' }, { filename: 'Lorem.txt' }, { byteLength: '3' }, { byteLength: 0 }]) {
        assert.equal((await request(root, 'POST', { ...body, operationId: randomUUID(), ...patch })).status, 400);
    }
    assert.equal((await request(`${root}/${result.item.id}`, 'GET', undefined, otherToken)).status, 404);
    const otherList = await request(root, 'GET', undefined, otherToken); assert.deepEqual((await otherList.json() as any).items, []);
    const list = await request(root); assertPrivateDto(await list.json()); assert.equal(puts, 0);
});

test('multipart Video owner and request-size admission happen before bytes or storage are accepted', async () => {
    const { result } = await create();
    const headers = { 'Content-Type': 'multipart/form-data; boundary=absent', 'Idempotency-Key': randomUUID(), 'If-Match': String(result.item.revision) };
    assert.equal((await request(`${root}/${result.item.id}/source`, 'POST', 'broken multipart', otherToken, headers)).status, 404);
    assert.equal((await request(`${root}/${result.item.id}/source`, 'POST', 'broken multipart', token, { ...headers, 'Idempotency-Key': 'invalid' })).status, 400);
    const code = await new Promise<number>((resolve, reject) => {
        const req = httpRequest(`${base}${root}/${result.item.id}/source`, { method: 'POST', headers: {
            Authorization: `Bearer ${token}`, ...headers, 'Content-Length': String((maxVideoUploadMb + 2) * 1024 ** 2)
        } }, response => { response.resume(); response.once('end', () => resolve(response.statusCode!)); });
        req.once('error', reject); req.end('x');
    });
    assert.equal(code, 413); assert.equal(puts, 0);
    const extra = new FormData(); extra.append('file', new Blob(['abc']), 'Lorem.MOV'); extra.append('extra', 'not allowed');
    const fields = await fetch(`${base}${root}/${result.item.id}/source`, { method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Idempotency-Key': randomUUID(), 'If-Match': String(result.item.revision) }, body: extra });
    assert.equal(fields.status, 400); assert.equal(puts, 0);
    const cancelled = await request(`${root}/${result.item.id}/cancel`, 'POST', { operationId: randomUUID(), expectedRevision: result.item.revision });
    assert.equal(cancelled.status, 202);
    assert.equal((await request(`${root}/${result.item.id}/source`, 'POST', 'broken multipart', token, headers)).status, 409);
    const fresh = await create('Lorem stale.MOV');
    const changed = await request(`${root}/${fresh.result.item.id}`, 'PATCH', { operationId: randomUUID(), expectedRevision: fresh.result.item.revision, patch: { title: 'Ipsum updated' } });
    assert.equal(changed.status, 200);
    assert.equal((await request(`${root}/${fresh.result.item.id}/source`, 'POST', 'broken multipart', token, { ...headers, 'Idempotency-Key': randomUUID(), 'If-Match': String(fresh.result.item.revision) })).status, 409);
    assert.equal(puts, 0);
});

test('Video tasks sort and continue by creation time rather than their hashed operation identities', async () => {
    const first = await create('Lorem first.MOV'), second = await create('Lorem second.MOV');
    const [newest, oldest] = [first.result.item, second.result.item].sort((left, right) => left.id.localeCompare(right.id));
    await getDb()!.collection('adminVideoProjects').updateOne({ _id: new ObjectId(newest.id) }, { $set: { createdAt: new Date('2026-01-02T00:00:00Z') } });
    await getDb()!.collection('adminVideoProjects').updateOne({ _id: new ObjectId(oldest.id) }, { $set: { createdAt: new Date('2026-01-01T00:00:00Z') } });
    const response = await request(root), body: any = await response.json(); assert.equal(response.status, 200);
    assert.deepEqual(body.items.map((item: any) => item.id), [newest.id, oldest.id]); assertPrivateDto(body);
    const continued = await request(`${root}?cursor=${newest.id}`); assert.equal(continued.status, 200);
    assert.deepEqual((await continued.json() as any).items.map((item: any) => item.id), [oldest.id]);
    const other = await request(root, 'POST', { operationId: randomUUID(), filename: 'Lorem other.MOV', byteLength: 3 }, otherToken);
    assert.equal(other.status, 201); const otherId = (await other.json() as any).item.id;
    assert.ok([400, 404].includes((await request(`${root}?cursor=${otherId}`)).status));
});

test('Unicode original MOV upload is private, byte-preserving and replay never dispatches another PUT', async () => {
    const filename = '示例原片.MOV', { result, bytes } = await create(filename), operationId = randomUUID();
    const first = await upload(result.item.id, 'source', new Blob([bytes], { type: 'video/quicktime' }), filename, result.item.revision, operationId);
    assert.equal(first.status, 200); const body: any = await first.json(); assertPrivateDto(body);
    assert.equal(body.item.source.filename, filename); assert.equal(body.item.source.status, 'ready'); assert.equal(body.item.processing.state, 'queued'); assert.equal(body.item.approvalDigest, null);
    assert.deepEqual([...objects.values()][0].bytes, bytes); assert.equal(puts, 1);
    const replay = await upload(result.item.id, 'source', new Blob([bytes], { type: 'application/octet-stream' }), filename, result.item.revision, operationId);
    assert.equal(replay.status, 200); assert.equal(puts, 1);
    const fresh = await request(`${root}/${result.item.id}`); assert.equal(fresh.status, 200); assertPrivateDto(await fresh.json());
    assert.equal((await request(`${root}/${result.item.id}/publish`, 'POST', { operationId: randomUUID(), expectedRevision: body.item.revision, approvalDigest: `vp_${'0'.repeat(64)}` })).status, 409);
});

test('the frontend multipart filename-star envelope preserves NFC Chinese originals and their replay identity', async () => {
    for (const [extension, contentType] of [['MOV', 'video/quicktime'], ['mp4', 'application/octet-stream']] as const) {
        const filename = `示例电影-Cafe\u0301.${extension}`.normalize('NFC');
        const { result, bytes } = await create(filename), operationId = randomUUID(), boundary = `FinitudeVideo-${operationId}`, before = puts;
        const encoded = encodeURIComponent(filename).replace(/['()*]/g, character => `%${character.charCodeAt(0).toString(16)}`);
        // Freeze the browser envelope independently: the ASCII fallback must not replace filename*.
        const body = Buffer.concat([
            Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="upload"; filename*=UTF-8''${encoded}\r\nContent-Type: ${contentType}\r\n\r\n`),
            bytes, Buffer.from(`\r\n--${boundary}--\r\n`)
        ]);
        const send = () => fetch(`${base}${root}/${result.item.id}/source`, { method: 'POST', headers: {
            Authorization: `Bearer ${token}`, 'Content-Type': `multipart/form-data; boundary=${boundary}`,
            'Idempotency-Key': operationId, 'If-Match': String(result.item.revision)
        }, body });
        const first = await send(); assert.equal(first.status, 200); const accepted: any = await first.json();
        assertPrivateDto(accepted);
        assert.deepEqual(accepted.item.source, { filename, byteLength: bytes.length, status: 'ready', operationId });
        assert.equal(accepted.receipt.operationId, operationId); assert.equal(accepted.item.processing.state, 'queued');
        assert.equal(accepted.item.approvalDigest, null); assert.equal(puts, before + 1);
        assert.deepEqual([...objects.values()].at(-1)!.bytes, bytes);
        const replay = await send(); assert.equal(replay.status, 200); const repeated: any = await replay.json();
        assert.deepEqual(repeated.item.source, accepted.item.source); assert.equal(repeated.receipt.operationId, operationId);
        assert.equal(puts, before + 1);
        const stored = await getDb()!.collection('adminVideoProjects').findOne({ _id: new ObjectId(result.item.id) });
        assert.equal(stored?.assets.filter((asset: any) => asset.kind === 'source').length, 1);
    }
});

test('cover uploads validate actual image bytes and previews retain owner, role and exact viewer fencing', async () => {
    const { result } = await create();
    const invalid = await upload(result.item.id, 'covers', new Blob(['not an image'], { type: 'image/png' }), 'Lorem.png', result.item.revision);
    assert.equal(invalid.status, 400); assert.equal(puts, 0);
    const png = await sharp({ create: { width: 8, height: 6, channels: 3, background: '#246824' } }).png().toBuffer();
    const accepted = await upload(result.item.id, 'covers', new Blob([png], { type: 'image/png' }), 'Lorem.png', result.item.revision);
    assert.equal(accepted.status, 200); const body: any = await accepted.json(); assertPrivateDto(body); assert.equal(puts, 1);
    const preview = body.item.covers[0].previewUrl, plain = preview.split('?')[0], cookie = { Cookie: `session_token=${token}` };
    assert.equal((await request(plain, 'GET', undefined, '', cookie)).status, 409);
    assert.equal((await request(`${plain}?viewer=${otherAdmin}`, 'GET', undefined, '', cookie)).status, 409);
    assert.equal((await request(preview, 'GET', undefined, '', { ...cookie, 'X-Finitude-Account-Viewer': otherAdmin.toHexString() })).status, 409);
    assert.equal((await request(preview, 'GET', undefined, otherToken)).status, 409);
    assert.equal((await request(plain, 'GET', undefined, otherToken)).status, 404);
    assert.equal((await request(preview, 'GET', undefined, userToken)).status, 403); assert.equal(reads, 0);
    const response = await request(preview, 'GET', undefined, '', cookie); assert.equal(response.status, 200); assert.match(response.headers.get('cache-control')!, /no-store/); assert.match(response.headers.get('content-type')!, /image\/jpeg/);
    assert.deepEqual(Buffer.from(await response.arrayBuffer()), [...objects.values()][0].bytes); assert.equal(reads, 1);
    await getDb()!.collection('users').updateOne({ _id: actor }, { $set: { role: 'user' } });
    assert.equal((await request(preview, 'GET', undefined, '', cookie)).status, 403); assert.equal(reads, 1);
});
